CREATE TABLE "TB_BRF_CASE" (
  "CASE_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "MKT_BASE_DT" DATE NOT NULL,
  "BRF_TP" VARCHAR(20) NOT NULL,
  "KR_MKT_DT" DATE,
  "US_MKT_DT" DATE,
  "FX_BASE_DT" DATE,
  "RATE_BASE_DT" DATE,
  "AS_OF_DTTM" TIMESTAMPTZ NOT NULL,
  "CASE_STS" VARCHAR(20) NOT NULL DEFAULT 'READY',
  "REMARK" VARCHAR(2000),
  "CRT_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "UK_TB_BRF_CASE_01" UNIQUE ("MKT_BASE_DT","BRF_TP"),
  CONSTRAINT "CK_TB_BRF_CASE_01" CHECK ("BRF_TP" IN ('DAILY','WEEKLY','MONTHLY','AD_HOC')),
  CONSTRAINT "CK_TB_BRF_CASE_02" CHECK ("CASE_STS" IN ('READY','PARTIAL','COMPLETE','FAILED'))
);

ALTER TABLE "TB_LEGACY_BRF" ADD COLUMN "CASE_ID" BIGINT REFERENCES "TB_BRF_CASE"("CASE_ID");
ALTER TABLE "TB_HIST_RECALC_RUN" ADD COLUMN "CASE_ID" BIGINT REFERENCES "TB_BRF_CASE"("CASE_ID");

INSERT INTO "TB_BRF_CASE"("MKT_BASE_DT","BRF_TP","AS_OF_DTTM","CASE_STS","REMARK")
SELECT "MARKET_BASE_DT",COALESCE("BRF_TP",'AD_HOC'),
       COALESCE("GENERATED_DTTM",("MARKET_BASE_DT"::timestamp + TIME '08:00') AT TIME ZONE 'Asia/Seoul'),
       CASE WHEN "RECOVERY_STS"='RECOVERED' THEN 'READY' ELSE 'PARTIAL' END,
       "ISSUE_TXT"
  FROM "TB_LEGACY_BRF" WHERE "MARKET_BASE_DT" IS NOT NULL
ON CONFLICT("MKT_BASE_DT","BRF_TP") DO NOTHING;

UPDATE "TB_LEGACY_BRF" l SET "CASE_ID"=c."CASE_ID"
  FROM "TB_BRF_CASE" c
 WHERE c."MKT_BASE_DT"=l."MARKET_BASE_DT" AND c."BRF_TP"=COALESCE(l."BRF_TP",'AD_HOC');
UPDATE "TB_HIST_RECALC_RUN" r SET "CASE_ID"=c."CASE_ID"
  FROM "TB_BRF_CASE" c
 WHERE c."MKT_BASE_DT"=r."BASE_DT" AND c."BRF_TP"='DAILY';

CREATE TABLE "TB_HIST_RECALC_INPUT" (
  "RECALC_INPUT_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "HIST_RECALC_RUN_ID" BIGINT NOT NULL REFERENCES "TB_HIST_RECALC_RUN"("HIST_RECALC_RUN_ID") ON DELETE CASCADE,
  "INPUT_CD" VARCHAR(50) NOT NULL,
  "REQUIRED_YN" CHAR(1) NOT NULL,
  "AVAILABLE_YN" CHAR(1) NOT NULL,
  "BASE_DT" DATE,
  "AVAILABLE_DTTM" TIMESTAMPTZ,
  "SOURCE_CD" VARCHAR(50),
  "SOURCE_VER" VARCHAR(100),
  "VALUE_NUM" NUMERIC(30,10),
  "MISSING_RSN" VARCHAR(1000),
  "RECONSTRUCTION_METHOD" VARCHAR(30) NOT NULL,
  "CRT_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "UK_TB_HIST_RECALC_INPUT_01" UNIQUE ("HIST_RECALC_RUN_ID","INPUT_CD"),
  CONSTRAINT "CK_TB_HIST_RECALC_INPUT_01" CHECK ("REQUIRED_YN" IN ('Y','N') AND "AVAILABLE_YN" IN ('Y','N')),
  CONSTRAINT "CK_TB_HIST_RECALC_INPUT_02" CHECK ("RECONSTRUCTION_METHOD" IN ('RAW','SNAPSHOT','DERIVED','NOT_AVAILABLE'))
);
CREATE INDEX "IDX_TB_HIST_RECALC_INPUT_01" ON "TB_HIST_RECALC_INPUT" ("INPUT_CD","BASE_DT" DESC);

INSERT INTO "TB_HIST_RECALC_INPUT"("HIST_RECALC_RUN_ID","INPUT_CD","REQUIRED_YN","AVAILABLE_YN","BASE_DT",
 "SOURCE_CD","SOURCE_VER","MISSING_RSN","RECONSTRUCTION_METHOD")
SELECT r."HIST_RECALC_RUN_ID",a.key,'Y',CASE WHEN (a.value#>>'{}')::bigint>0 THEN 'Y' ELSE 'N' END,
       CASE WHEN r."INPUT_BASE_DT_JSON" ? a.key THEN (r."INPUT_BASE_DT_JSON"->>a.key)::date END,
       CASE WHEN a.key LIKE 'DGS%' THEN 'FRED' WHEN a.key='USD_KRW' THEN 'YAHOO' WHEN a.key='VIX' THEN 'YAHOO' ELSE 'KRX' END,
       r."CODE_VER",CASE WHEN (a.value#>>'{}')::bigint=0 THEN '과거 원천 데이터 없음' END,
       CASE WHEN (a.value#>>'{}')::bigint>0 THEN 'RAW' ELSE 'NOT_AVAILABLE' END
  FROM "TB_HIST_RECALC_RUN" r CROSS JOIN LATERAL jsonb_each(r."AVAILABILITY_JSON") a
ON CONFLICT("HIST_RECALC_RUN_ID","INPUT_CD") DO NOTHING;

INSERT INTO "TB_HIST_RECALC_INPUT"("HIST_RECALC_RUN_ID","INPUT_CD","REQUIRED_YN","AVAILABLE_YN","SOURCE_VER",
 "MISSING_RSN","RECONSTRUCTION_METHOD")
SELECT r."HIST_RECALC_RUN_ID",m.value,'Y','N',r."CODE_VER",'재계산 입력 Snapshot에 값이 없음','NOT_AVAILABLE'
  FROM "TB_HIST_RECALC_RUN" r CROSS JOIN LATERAL jsonb_array_elements_text(r."MISSING_INPUT_JSON") m(value)
ON CONFLICT("HIST_RECALC_RUN_ID","INPUT_CD") DO NOTHING;

ALTER TABLE "TB_BRF_EVAL"
  ADD COLUMN "CASE_ID" BIGINT REFERENCES "TB_BRF_CASE"("CASE_ID"),
  ADD COLUMN "BASE_PRC" NUMERIC(30,10),
  ADD COLUMN "END_PRC" NUMERIC(30,10),
  ADD COLUMN "VOLATILITY_RT" NUMERIC(12,6),
  ADD COLUMN "OUTCOME_CLASS" VARCHAR(30),
  ADD COLUMN "DATA_VER" VARCHAR(100) NOT NULL DEFAULT 'HIST_20260830_V1',
  ADD COLUMN "END_DT" DATE;
ALTER TABLE "TB_BRF_EVAL" ALTER COLUMN "DATA_VER" DROP DEFAULT;

COMMENT ON TABLE "TB_BRF_CASE" IS 'LEGACY, 알고리즘별 재계산, 시장성과를 연결하는 역사 브리핑 Case';
COMMENT ON TABLE "TB_HIST_RECALC_INPUT" IS '역사 재계산에 사용한 입력별 가용성, 기준일, 값 및 재구성 계보';
COMMENT ON COLUMN "TB_BRF_CASE"."AS_OF_DTTM" IS '미래정보 누출 검사의 기준이 되는 당시 브리핑 시각';
